<?php
declare(strict_types=1);
use PHPUnit\Framework\TestCase;
if(!function_exists('is_wp_error')){function is_wp_error(mixed $value):bool{return $value instanceof WP_Error;}}
use DigiForge\Connector\Printify\{ReadConnector,HostInterface,ShopBinding,CredentialReference,ExternalOperationIntent,ProviderResult};
use DigiForge\POD\PrintifyCatalogClient;
spl_autoload_register(static function(string $class):void { $prefix='DigiForge\\Connector\\Printify\\';if(str_starts_with($class,$prefix)){ $file=__DIR__.'/../../includes/Connector/Printify/'.substr($class,strlen($prefix)).'.php';if(is_file($file))require_once $file; }});
require_once __DIR__.'/../../includes/POD/PrintifyCatalogClient.php';
require_once __DIR__.'/../../includes/POD/PrintifyConnectorReadContract.php';
final class PrintifyConnectorV1Test extends TestCase {
 protected function setUp():void{self::assertTrue(class_exists(ReadConnector::class),'Versioned DigiForge read service required');}
 private function intent(string $op='PRODUCTS_READ',array $input=[]):ExternalOperationIntent{return new ExternalOperationIntent(1,'personalized_pod',3,$op,$input,str_repeat('a',32));}
 private function host(array $ownedUploads=[]):HostInterface {return new class($ownedUploads) implements HostInterface {
  public function __construct(private array $ownedUploads){}
  public int $authorizations=0;public int $credentials=0;public int $reservations=0;public bool $locked=false;public bool $audit=true;public array $receipts=[];
  public function authorize(ExternalOperationIntent $i):ShopBinding|WP_Error{$this->authorizations++;return $this->locked?new WP_Error('locked','Denied'):new ShopBinding(2,'personalized_pod',3,'28930593','production',1,new CredentialReference(3),hash('sha256','binding'),time()+300,$this->ownedUploads);}
  public function reserve(ExternalOperationIntent $i,ShopBinding $b):true|WP_Error{$this->reservations++;return true;}
  public function consume(CredentialReference $r,callable $f):mixed{$this->credentials++;return $f('synthetic_fixture_token');}
  public function record(array $r):bool{$this->receipts[]=$r;return $this->audit;}
 };}
 public function testReadProjectsProductMetadataAndCorrelatesReceipt():void{$h=$this->host();$calls=0;$c=new ReadConnector($h,new PrintifyCatalogClient(function($u,$a)use(&$calls){$calls++;return ['response'=>['code'=>200],'body'=>'{"data":[{"id":"p1","title":"Mug","blueprint_id":1,"print_provider_id":2,"variants":[{"id":3,"is_enabled":true}],"secret":"never","buyer_email":"private@test.invalid"}],"current_page":1,"last_page":2}'];}));$r=$c->read($this->intent());self::assertInstanceOf(ProviderResult::class,$r);self::assertSame('1.0.0',$c->version());self::assertSame('p1',$r->data['items'][0]['id']);self::assertStringNotContainsString('private@',json_encode($r));self::assertStringNotContainsString('synthetic_fixture_token',json_encode($h->receipts));self::assertSame(1,$calls);self::assertGreaterThanOrEqual(3,$h->authorizations);self::assertSame(1,$h->credentials);self::assertCount(2,$h->receipts);}
 public function testStopDeniesBeforeVaultAndTransport():void{$h=$this->host();$h->locked=true;$calls=0;$c=new ReadConnector($h,new PrintifyCatalogClient(function()use(&$calls){$calls++;return [];}));self::assertInstanceOf(WP_Error::class,$c->read($this->intent()));self::assertSame(0,$h->credentials);self::assertSame(0,$calls);}
 public function testUnavailableAuditDeniesBeforeCredentials():void{$h=$this->host();$h->audit=false;$c=new ReadConnector($h,new PrintifyCatalogClient(fn()=>[]));self::assertInstanceOf(WP_Error::class,$c->read($this->intent()));self::assertSame(0,$h->credentials);}
 public function testPostResponseRevocationDeniesData():void{$h=$this->host();$c=new ReadConnector($h,new PrintifyCatalogClient(function()use($h){$h->locked=true;return ['response'=>['code'=>200],'body'=>'{"data":[]}'];}));self::assertInstanceOf(WP_Error::class,$c->read($this->intent()));}
 public function testOrdersNeverExposeBuyerPersonalData():void{$h=$this->host();$c=new ReadConnector($h,new PrintifyCatalogClient(fn()=>['response'=>['code'=>200],'body'=>'{"id":"o1","status":"pending","address_to":{"email":"private@example.test","address1":"Secret street"},"line_items":[{"variant_id":7,"quantity":1}],"shipments":[{"carrier":"UPS","number":"secret-tracking"}]}']));$r=$c->read($this->intent('ORDER_READ',['order_id'=>'o1']));self::assertInstanceOf(ProviderResult::class,$r);self::assertSame('o1',$r->data['items'][0]['id']);self::assertStringNotContainsString('Secret street',json_encode($r));self::assertStringNotContainsString('private@',json_encode($r));self::assertStringNotContainsString('secret-tracking',json_encode($r));}
 public function testShopDiscoveryProjectsOnlyBoundIdentity():void{$h=$this->host();$c=new ReadConnector($h,new PrintifyCatalogClient(fn()=>['response'=>['code'=>200],'body'=>'[{"id":28930593,"title":"Bound"},{"id":28925875,"title":"Other private shop"}]']));$r=$c->read($this->intent('SHOPS_READ'));self::assertInstanceOf(ProviderResult::class,$r);self::assertCount(1,$r->data['items']);self::assertStringNotContainsString('Other private',json_encode($r));}
 public function testUnsafeIntentRejected():void{$this->expectException(InvalidArgumentException::class);$this->intent('PRODUCT_PUBLISH');}
 public function testBindingCannotAliasShop():void{$this->expectException(InvalidArgumentException::class);new ShopBinding(3,'personalized_pod',3,'28930593','production',1,new CredentialReference(3),hash('sha256','b'),time()+300);}
 public function testOfficialProductOptionObjectsAndPrintAreasRemainBoundedMetadata():void{$h=$this->host();$body=['id'=>'p1','options'=>[['name'=>'Color','type'=>'color','values'=>[['id'=>1,'title'=>'White','colors'=>['#ffffff']]]]],'print_areas'=>[['variant_ids'=>[7],'placeholders'=>[['position'=>'front','images'=>[['id'=>'asset1','x'=>0.5,'y'=>0.5,'scale'=>1.0,'angle'=>0]]]]]]];$c=new ReadConnector($h,new PrintifyCatalogClient(fn()=>['response'=>['code'=>200],'body'=>json_encode($body)]));$r=$c->read($this->intent('PRODUCT_READ',['product_id'=>'p1']));self::assertInstanceOf(ProviderResult::class,$r);self::assertSame('White',$r->data['items'][0]['options'][0]['values'][0]['title']);self::assertSame([7],$r->data['items'][0]['print_areas'][0]['variant_ids']);}
 public function testWrongReturnedResourceFailsClosed():void{$h=$this->host();$c=new ReadConnector($h,new PrintifyCatalogClient(fn()=>['response'=>['code'=>200],'body'=>'{"id":"different"}']));self::assertInstanceOf(WP_Error::class,$c->read($this->intent('PRODUCT_READ',['product_id'=>'p1'])));}
 public function testReflectedJsonEscapedCredentialIsRejected():void{$h=$this->host();$c=new ReadConnector($h,new PrintifyCatalogClient(fn()=>['response'=>['code'=>200],'body'=>'{"id":"p1","title":"\\u0073ynthetic_fixture_token"}']));self::assertInstanceOf(WP_Error::class,$c->read($this->intent('PRODUCT_READ',['product_id'=>'p1'])));}
 public function testUnownedUploadCannotBeReadThroughBoundShop():void{$h=$this->host();$c=new ReadConnector($h,new PrintifyCatalogClient(fn()=>['response'=>['code'=>200],'body'=>'{"id":"unowned","width":100}']));self::assertInstanceOf(WP_Error::class,$c->read($this->intent('UPLOAD_READ',['upload_id'=>'unowned'])));}
 public function testUploadListingOnlyReturnsReceiptOwnedReferences():void{$h=$this->host(['owned']);$c=new ReadConnector($h,new PrintifyCatalogClient(fn()=>['response'=>['code'=>200],'body'=>'{"data":[{"id":"owned","width":100},{"id":"other","width":200}]}']));$r=$c->read($this->intent('UPLOADS_READ'));self::assertInstanceOf(ProviderResult::class,$r);self::assertSame(['owned'],array_column($r->data['items'],'id'));}
 public function testRateLimitReachesCallerOnlyAsBoundedNonSecretEvidence():void{$h=$this->host();$c=new ReadConnector($h,new PrintifyCatalogClient(fn()=>['response'=>['code'=>429],'headers'=>['retry-after'=>'120'],'body'=>'{"private":"not disclosed"}']));$r=$c->read($this->intent());self::assertInstanceOf(WP_Error::class,$r);$d=method_exists($r,'get_error_data')?$r->get_error_data():$r->data;self::assertSame('RATE_LIMIT',$d['category']??null);self::assertSame(60,$d['retry_after_seconds']??null);self::assertFalse($d['retry_permitted']);}
 public function testOfficialV2ShippingJsonApiMethodsAndRegionalCosts():void{foreach(['shipping-methods-v2.json'=>[], 'shipping-standard-v2.json'=>['shipping_method'=>'standard']] as $file=>$extra){$body=file_get_contents(__DIR__.'/../fixtures/printify-connector/'.$file);$h=$this->host();$c=new ReadConnector($h,new PrintifyCatalogClient(fn()=>['response'=>['code'=>200],'body'=>$body]));$r=$c->read($this->intent('SHIPPING_READ',['blueprint_id'=>1,'provider_id'=>2]+$extra));self::assertInstanceOf(ProviderResult::class,$r);if($extra){self::assertSame('US',$r->data['items'][0]['country']);self::assertSame(399,$r->data['items'][0]['shipping_cost']['first_item']['amount']);}else{self::assertSame('standard',$r->data['items'][0]['name']);}}}
 public function testOrderProjectionRetainsNonPersonalVariantMapping():void{$h=$this->host();$body=['id'=>'o1','status'=>'fulfilled','line_items'=>[['product_id'=>'p1','variant_id'=>7,'print_provider_id'=>8,'quantity'=>2,'metadata'=>['title'=>'Private buyer name']]],'shipments'=>[['carrier'=>'UPS','number'=>'never','url'=>'https://private.invalid']]];$c=new ReadConnector($h,new PrintifyCatalogClient(fn()=>['response'=>['code'=>200],'body'=>json_encode($body)]));$r=$c->read($this->intent('ORDER_READ',['order_id'=>'o1']));self::assertInstanceOf(ProviderResult::class,$r);self::assertArrayHasKey('line_items',$r->data['items'][0]);self::assertSame('p1',$r->data['items'][0]['line_items'][0]['product_id']);self::assertSame(7,$r->data['items'][0]['line_items'][0]['variant_id']);self::assertSame(2,$r->data['items'][0]['line_items'][0]['quantity']);self::assertStringNotContainsString('Private buyer',json_encode($r));self::assertStringNotContainsString('private.invalid',json_encode($r));}
}
